def apply_chapter_insights():
    path = ROOT / "chapter_insights" / "11_1_kings.json"
    data = load(path)
    for n in range(1, 23):
        entry = data[f"1 Kings {n}"]
        info = CH[n]
        entry["summary"] = info["summary"]
        entry["whereWeAre"] = info["wwa"]
        entry["keyFigures"] = [{"name": a, "role": b} for a, b in info["figures"]]
        if len(entry["keyThemes"]) > len(info["themes"]):
            entry["keyThemes"] = entry["keyThemes"][: len(info["themes"])]
        elif len(entry["keyThemes"]) < len(info["themes"]):
            raise SystemExit(f"1 Kings {n}: only {len(entry['keyThemes'])} theme rows but {len(info['themes'])} supplied")
        for theme, (name, explanation) in zip(entry["keyThemes"], info["themes"]):
            theme["theme"] = name
            theme["explanation"] = explanation
        if len(entry["whereWeAre"]) > 600 or len(entry["keyFigures"]) > 6:
            raise SystemExit(f"1 Kings {n}: WWA {len(entry['whereWeAre'])} chars or {len(entry['keyFigures'])} figures")
    save(path, data)
    print(f"Updated {path.relative_to(ROOT)}")


def apply_book_overview():
    path = ROOT / "book_overviews" / "02_early_history.json"
    data = load(path)
    book = data["1 Kings"]
    book["movements"] = [
        {"title": "Solomon's Reign and Temple", "description": "Solomon receives wisdom, builds the temple, and reaches great prosperity.", "passages": ["1 Kings 1-10"]},
        {"title": "The Kingdom Divides", "description": "Solomon's later idolatry is followed by the split between Israel in the north and Judah in the south, and by a line of kings in both lands.", "passages": ["1 Kings 11-16"]},
        {"title": "Elijah Confronts Ahab", "description": "Elijah challenges Baal worship and the policies of Ahab and Jezebel.", "passages": ["1 Kings 17-22"]},
    ]
    save(path, data)
    print(f"Updated {path.relative_to(ROOT)}")


STORY_FIXES = [
    ("saying, I will be king.” his father had never corrected him.", "saying, I will be king.” His father had never corrected him."),
    ("“did worse than all that were before him.” his son Ahab becomes king", "“did worse than all that were before him.” His son Ahab becomes king"),
    ("calls them Cabul, meaning good for nothing", "calls them Cabul, meaning displeasing"),
    ("And He adds what Solomon did not ask for", "And he adds what Solomon did not ask for"),
    ("God appears to him a second time, as He did at Gibeon. He says He has heard Solomon's prayer", "God appears to him a second time, as he did at Gibeon. God says he has heard Solomon's prayer"),
    ("and He will leave one tribe for Solomon's son", "and he will leave one tribe for Solomon's son"),
    ("He will give them into Ahab's hand again", "he will give them into Ahab's hand again"),
    ("Ahab Dies in Battle and Ahaziah Succeeds him", "Ahab Dies in Battle and Ahaziah Succeeds Him"),
]


def apply_story_fixes():
    path = ROOT / "book_content" / "03_later_history.md"
    text = path.read_text(encoding="utf-8")
    start = text.index("# 1 Kings")
    try:
        end = text.index("\n# ", start + 5) + 1
    except ValueError:
        end = len(text)
    section = text[start:end]
    for old, new in STORY_FIXES:
        if section.count(old) == 0 and section.count(new) >= 1:
            continue
        if section.count(old) == 0:
            print(f"story fix skipped (not found): {old!r}")
            continue
        section = section.replace(old, new)
    path.write_text(text[:start] + section + text[end:], encoding="utf-8")
    print(f"Updated {path.relative_to(ROOT)}")


if __name__ == "__main__":
    apply_chapter_insights()
    apply_book_overview()
    apply_story_fixes()
